    while Workspace:GetServerTimeNow() < hit + jitter - 0.012 do RunService.Heartbeat:Wait() end
    local list, b = rawget(C, "_bubbles"), nil
    if type(list) == "table" then
        b = list[id]
        if not b then for _, x in pairs(list) do if type(x) == "table" and x.id == id then b = x; break end end end
    end
    if not b or b.answered or not on("aw_auto") then return end
    b.__cw = true
