function MG.ahStep(self)
    local m, surf, side = self._myMallet, self._surface, self._mySide
    local model = self._tableModel
    local puck = model and model:FindFirstChild("Puck", true)
    if not (m and surf and side and puck) then return MG.ahOrig(self) end
    local now = os.clock()
    local dt = math.clamp(now - (MG.ah_t or now), 1 / 240, 0.1)
    MG.ah_t = now
    local cf, half = surf.CFrame, surf.Size / 2
    local sgn = side == "left" and 1 or -1
    local rm, rp = m.Size.X / 2, puck.Size.X / 2
    local W, L = half.X - rm, half.Z
    local pl = cf:PointToObjectSpace(puck.Position)
    local px, pu = pl.X, pl.Z * sgn
    local ml = cf:PointToObjectSpace(m.Position)
    local mx, mu = ml.X, ml.Z * sgn
    local vx, vu = 0, 0
    if MG.ah_lp then
        vx = (px - MG.ah_lp.X) / dt
        vu = (pu - MG.ah_lp.Y) / dt
        if MG.ah_lv then vx, vu = MG.ah_lv.X * 0.5 + vx * 0.5, MG.ah_lv.Y * 0.5 + vu * 0.5 end
    end
    MG.ah_lp, MG.ah_lv = Vector2.new(px, pu), Vector2.new(vx, vu)
    local defU = L - 1.1
    local tx, tu
    if pu > -0.3 then
        local p = Vector2.new(px, pu)
        local om = model:FindFirstChild(side == "left" and "MalletRight" or "MalletLeft", true)
        local ol = om and cf:PointToObjectSpace(om.Position)
        local o = ol and Vector2.new(ol.X, ol.Z * sgn) or Vector2.new(0, -L + 0.5)
        local span = half.X - rp
        local function clear(g, mirrorX)
            local seg = g - p
            local function dist(q)
                local t = math.clamp((q - p):Dot(seg) / seg:Dot(seg), 0, 1)
                return (p + seg * t - q).Magnitude
            end
            local c = dist(o)
            if mirrorX then c = math.min(c, dist(Vector2.new(mirrorX - o.X, o.Y))) end
            return c
        end
        local best, bestC = Vector2.new(0, -L), clear(Vector2.new(0, -L))
        for _, wx in ipairs({ span, -span }) do
            local g = Vector2.new(2 * wx, -L)
            local c = clear(g, 2 * wx) - 0.05
            if c > bestC then best, bestC = g, c end
        end
        MG.ah_shot = best.X == 0 and "straight" or (best.X > 0 and "bank R" or "bank L")
        local dir = (best - p).Unit
        local behind = p - dir * (rm + rp + 0.05)
        local me = Vector2.new(mx, mu)
        if (me - p):Dot(dir) < -0.1 and (me - behind).Magnitude < 0.6 then
            local hit = p + dir * 1.2
            tx, tu = hit.X, hit.Y
        elseif (me - p):Dot(dir) >= -0.1 then
            local side2 = (mx >= px) and 1 or -1
            tx, tu = px + side2 * (rm + rp + 0.3), pu + (rm + rp + 0.3)
        else
            tx, tu = behind.X, behind.Y
        end
        if vu > 6 and pu > 0 then
            local t = (defU - pu) / vu
            local x = px + vx * math.max(t, 0)
            local span = half.X - rp
            for _ = 1, 4 do if x > span then x = 2 * span - x elseif x < -span then x = -2 * span - x end end
            tx, tu = x, defU
        end
    else
        local x = px * 0.6
        if vu > 1 then
            local t = (defU - pu) / vu
            x = px + vx * t
            local span = half.X - rp
            for _ = 1, 4 do if x > span then x = 2 * span - x elseif x < -span then x = -2 * span - x end end
        end
        tx, tu = x, defU
    end
    tx = math.clamp(tx, -W, W)
    tu = math.clamp(tu, rm + 0.02, L - rm)
    local d = Vector2.new(tx - mx, tu - mu)
    local maxStep = 27.5 * dt
    if d.Magnitude > maxStep then d = d.Unit * maxStep end
    local nx, nu = mx + d.X, mu + d.Y
    local world = (cf * CFrame.new(nx, ml.Y, nu * sgn)).Position
    m.CFrame = CFrame.new(world)
    pcall(function() self:_getRemotes().MalletMoved:FireServer(m.CFrame) end)
end
