            local stand = Eval.score(st) * sideSign(st)
            if stand >= beta then return stand end
            if stand > alpha then alpha = stand end
            if qd <= 0 then return stand end
            local caps = {}
            for _, m in ipairs(Moves.legal(st)) do if pieceAt(st, m.to) or m.flag == "ep" then caps[#caps + 1] = m end end
            order(st, caps)
            for _, m in ipairs(caps) do
                local _, undo = Moves.make(st, m)
                local v = -quiesce(st, -beta, -alpha, qd - 1)
                Moves.unmake(st, m, undo)
                if v >= beta then return v end
                if v > alpha then alpha = v end
            end
            return alpha
        end
        local function negamax(st, depth, alpha, beta, ply)
            nodes = nodes + 1
            if nodes % 600 == 0 then
                if os.clock() > deadline then aborted = true end
                task.wait()
            end
            if aborted then return 0 end
            local list = Moves.legal(st)
            if #list == 0 then
                if Moves.inCheck(st, st.side) then return -MATE + ply end
                return 0
            end
            if depth <= 0 then return quiesce(st, alpha, beta, 3) end
            order(st, list)
            local best = -math.huge
            for _, m in ipairs(list) do
                local _, undo = Moves.make(st, m)
                local v = -negamax(st, depth - 1, -beta, -alpha, ply + 1)
                Moves.unmake(st, m, undo)
                if aborted then return 0 end
                if v > best then best = v end
                if v > alpha then alpha = v end
                if alpha >= beta then break end
            end
            return best
        end
        function MG.chBest(fen, maxTime, maxDepth)
            local st = Board.fromFEN(fen)
            local root = Moves.legal(st)
            if #root == 0 then return nil end
            order(st, root)
            local bestMove, bestDepth = root[1], 0
            deadline, aborted, nodes = os.clock() + (maxTime or 1.5), false, 0
            for depth = 1, (maxDepth or 5) do
                local alpha, cur, curV = -math.huge, nil, -math.huge
                for _, m in ipairs(root) do
                    local _, undo = Moves.make(st, m)
                    local v = -negamax(st, depth - 1, -math.huge, -alpha, 1)
                    Moves.unmake(st, m, undo)
                    if aborted then break end
                    if v > curV then curV, cur = v, m end
                    if v > alpha then alpha = v end
                end
                if aborted then break end
                bestMove, bestDepth = cur, depth
                for i, m in ipairs(root) do if m == cur then table.remove(root, i); table.insert(root, 1, m); break end end
                if curV >= MATE - 100 then break end
            end
            return bestMove, bestDepth, nodes
        end
    end
end
function MG.chFind()
    if MG.chst then return MG.chst end
    for _, f in ipairs(getgc(false)) do
        if type(f) == "function" and islclosure(f) then
            local ok, info = pcall(debug.getinfo, f)
            if ok and info and info.name == "attemptSelectOrMove" and tostring(info.source):find("Chess") then
                local u = debug.getupvalues(f)
                if type(u[1]) == "table" then MG.chst = u[1]; break end
            end
        end
    end
    return MG.chst
end
function MG.chLoop()
    if not on("ch_auto") or not MG.chBest then return end
    local st = MG.chFind(); if not st then return end
    local m = st.mirror
    if not (st.active and m) then return end
    local ok, fen = pcall(m.fen, m); if not ok then return end
    local side = fen:match("^%S+ (%a)")
    local mine = side == st.myColor
    if not (mine or st.solo) or fen == MG.chLast then return end
    MG.chLast = fen
    task.wait(0.4 + math.random() * 0.6)
    local mv = MG.chBest(fen, mine and 2.5 or 0.3, mine and 6 or 1)
    if not mv then return end
    local rf = ReplicatedStorage.Remotes:FindFirstChild("ChessFunction")
    local piece = mv.promo and "q" or nil
    if rf and pcall(function() rf:InvokeServer("Chess_Move", { tableId = st.tableId, from = mv.from, to = mv.to, promo = piece }) end) then MG.ch = (MG.ch or 0) + 1 end
end
task.spawn(function()
    while RUNNING do
        if on("ch_auto") then pcall(MG.chLoop) end
        task.wait(0.3)
    end
end)
