function AA.target()
    local r = hrp(); if not r then return nil end
    local mode = val("aa_mode") or "NPCs"
    local onlyAggro = on("aa_aggro")
    local maxD = val("aa_range") or 60
    local best, bd
    local function consider(m)
        local mr, mh = m:FindFirstChild("HumanoidRootPart"), m:FindFirstChildOfClass("Humanoid")
        if not (mr and mh and mh.Health > 0) or m == lp.Character then return end
        if m:GetAttribute("Downed") or m:GetAttribute("Ragdoll") then return end
        local recent = AA.attackers[m] and os.clock() - AA.attackers[m] < 20
        if onlyAggro and not recent then return end
        local d = (mr.Position - r.Position).Magnitude
        if d <= maxD and (not bd or d < bd) then best, bd = m, d end
    end
    if mode == "Selected Player" then
        local p = MV.resolve(val("aa_player"))
        if p and p.Character then consider(p.Character) end
        return best
    end
    if mode == "NPCs" or mode == "Both" then
        local folder = Workspace:FindFirstChild("NPCs")
        for _, m in ipairs(folder and folder:GetChildren() or {}) do if m:GetAttribute("CanFight") then consider(m) end end
    end
    if mode == "Players" or mode == "Both" then
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= lp and p.Character then
                AA.fr = AA.fr or {}
                if on("aa_friends") and AA.fr[p.UserId] == nil then
                    AA.fr[p.UserId] = false
                    task.spawn(function() local ok, v = pcall(lp.IsFriendsWith, lp, p.UserId); AA.fr[p.UserId] = ok and v or false end)
                end
                local friend = on("aa_friends") and AA.fr[p.UserId]
                local staff = VS.st and VS.st.found and VS.st.found[p]
                if not friend and not staff then consider(p.Character) end
            end
        end
    end
    return best
end
