    if on("aa_flee") and h.Health < h.MaxHealth * (val("aa_retreat") or 30) / 100 then
        if not AA.fled or os.clock() - AA.fled > 6 then
            local threat, td
            local function chk(m)
                local mr = m and m:FindFirstChild("HumanoidRootPart")
                if mr and m ~= c then local d = (mr.Position - r.Position).Magnitude; if d < 40 and (not td or d < td) then threat, td = mr, d end end
            end
