            if threat and h.MoveDirection.Magnitude < 0.1 then
                local away = r.Position - threat.Position
                away = Vector3.new(away.X, 0, away.Z)
                away = away.Magnitude > 0.5 and away.Unit or Vector3.new(1, 0, 0)
                MV.unseat(); r.CFrame = CFrame.new(r.Position + away * 100); MV.land()
