            end
        end
        AA.state = L["Healing"]; AA.cur = nil
        return
    end
    if h.MoveDirection.Magnitude > 0.1 then AA.userAt = os.clock() end
    local userMoving = AA.userAt and os.clock() - AA.userAt < 1.5
    local m = AA.target()
    AA.cur = m
    if not m then AA.state = L["No target"]; return end
    local mr = m:FindFirstChild("HumanoidRootPart")
    if not c:GetAttribute("Equip") then AA.tap(Enum.KeyCode.T); task.wait(0.4) end
    local off = r.Position - mr.Position
    off = Vector3.new(off.X, 0, off.Z)
    off = off.Magnitude > 0.5 and off.Unit or Vector3.new(1, 0, 0)
    if (mr.Position - r.Position).Magnitude > 6 and on("aa_stick") and not userMoving then
