        LG.conns[#LG.conns + 1] = Lighting.DescendantAdded:Connect(function(d) if on("s_lag") and d:IsA("PostEffect") then pcall(function() d.Enabled = false end) end end)
    else
        LG.stopConns()
        LG.quality(false)
        pcall(function()
            Lighting.GlobalShadows = LG.saved.shadows
            if LG.saved.envd then Lighting.EnvironmentDiffuseScale = LG.saved.envd end
            if LG.saved.envs then Lighting.EnvironmentSpecularScale = LG.saved.envs end
            Workspace:SetAttribute("HairPhysicsBudget", LG.saved.hair)
        end)
        for k, v in pairs(LG.saved) do
            if typeof(k) == "Instance" then
                pcall(function() if k:IsA("Atmosphere") then k.Density = v else k.Enabled = v end end)
            end
        end
        local ter = Workspace:FindFirstChildOfClass("Terrain")
        if ter and LG.saved.deco ~= nil then pcall(function() ter.Decoration = LG.saved.deco end) end
        for part, s in pairs(LG.mats) do
            if typeof(part) == "Instance" then pcall(function() part.Material = s[1]; part.CastShadow = s[2]; part.Reflectance = s[3] end) end
        end
        LG.mats = setmetatable({}, { __mode = "k" })
        LG.saved = {}
    end
end
onClean(function() LG.stopConns(); if on("s_lag") then pcall(LG.set, false) end end)
local MEM = { tex = setmetatable({}, { __mode = "k" }), conns = {} }
function MEM.total() local ok, v = pcall(function() return game:GetService("Stats"):GetTotalMemoryUsageMb() end); return ok and v or 0 end
function MEM.tag(t) local ok, v = pcall(function() return game:GetService("Stats"):GetMemoryUsageMbForTag(Enum.DeveloperMemoryTag[t]) end); return ok and v or 0 end
function MEM.stripOne(d)
    pcall(function()
        if (d:IsA("Decal") or d:IsA("Texture")) and d.Texture ~= "" then MEM.tex[d] = MEM.tex[d] or d.Texture; d.Texture = ""
        elseif d:IsA("SurfaceAppearance") then MEM.tex[d] = MEM.tex[d] or d.Parent; d.Parent = nil end
    end)
end
function MEM.low(v)
    for _, c in ipairs(MEM.conns) do pcall(function() c:Disconnect() end) end
    MEM.conns = {}
    if v then
        task.spawn(function()
            local n = 0
            for _, d in ipairs(Workspace:GetDescendants()) do
                if not on("m_low") then break end
                MEM.stripOne(d); n = n + 1
                if n % 300 == 0 then task.wait() end
            end
        end)
        MEM.conns[#MEM.conns + 1] = Workspace.DescendantAdded:Connect(function(d) if on("m_low") then task.defer(MEM.stripOne, d) end end)
    else
        for d, orig in pairs(MEM.tex) do
            pcall(function() if d:IsA("SurfaceAppearance") then d.Parent = orig else d.Texture = orig end end)
        end
        MEM.tex = setmetatable({}, { __mode = "k" })
    end
end
