function MV.restore()
    local h = hum()
    if h and MV.ws0 then h.WalkSpeed = MV.ws0 end
    MV.ws0 = nil
end
function MV.land()
    local r = hrp(); if not r then return end
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.FilterDescendantsInstances = { lp.Character, Workspace:FindFirstChild("AreaHitboxes") }
    local hit = Workspace:Raycast(r.Position, Vector3.new(0, -500, 0), rp)
    r.AssemblyLinearVelocity = Vector3.zero
    if hit and r.Position.Y - hit.Position.Y > 4 then r.CFrame = CFrame.new(hit.Position + Vector3.new(0, 3, 0)) * r.CFrame.Rotation end
end
function MV.toPlayer(name)
    local p = MV.resolve(name)
    local c = p and p.Character
    local t, r = c and c:FindFirstChild("HumanoidRootPart"), hrp()
    if not (t and r) then notify(L["Pick a player first"]); return end
    MV.unseat()
    r.CFrame = t.CFrame * CFrame.new(0, 0, 4)
    r.AssemblyLinearVelocity = Vector3.zero
end
local UIS = game:GetService("UserInputService")
function MV.step(dt)
    local h, r = hum(), hrp()
    if not (h and r) then return end
    if on("mv_speed") and not on("mv_fly") then
        local md = h.MoveDirection
        local extra = math.max(0, (val("mv_speed_v") or 28) - h.WalkSpeed)
        if md.Magnitude > 0.05 and extra > 0 then r.CFrame = r.CFrame + Vector3.new(md.X, 0, md.Z) * extra * dt end
    end
    if on("mv_fly") then
        local cam = Workspace.CurrentCamera
        local md = h.MoveDirection
        local dir = Vector3.zero
        if md.Magnitude > 0.05 then
            local lv = cam.CFrame.LookVector
            local flat = Vector3.new(lv.X, 0, lv.Z)
            local pitch = flat.Magnitude > 0.01 and md:Dot(flat.Unit) or 0
            dir = md + Vector3.new(0, lv.Y * pitch, 0)
        end
        if not UIS:GetFocusedTextBox() then
            if UIS:IsKeyDown(Enum.KeyCode.Space) then dir = dir + Vector3.new(0, 1, 0) end
            if UIS:IsKeyDown(Enum.KeyCode.LeftControl) then dir = dir - Vector3.new(0, 1, 0) end
        end
        r.AssemblyLinearVelocity = (dir.Magnitude > 0 and dir.Unit or dir) * (val("mv_fly_v") or 50) + Vector3.new(0, Workspace.Gravity * dt, 0)
    end
    if on("tp_follow") then
        local p = MV.resolve(val("tp_player"))
        local t = p and p.Character and p.Character:FindFirstChild("HumanoidRootPart")
        if t then r.CFrame = t.CFrame * CFrame.new(0, 0, 4); r.AssemblyLinearVelocity = Vector3.zero end
    end
end
