function ST.isStaffRank(rk) rk = tonumber(rk) or 0; return ST.ranks[rk] or rk >= 100 end
function ST.check(p)
    if p == lp then return end
    task.spawn(function()
        local staff = ST.ids[p.UserId]
        if not staff then
            local rk = p:GetAttribute("BillboardGroupRank")
            if rk == nil then local ok, v = pcall(function() return p:GetRankInGroup(416091513) end); rk = ok and v or 0 end
            staff = ST.isStaffRank(rk)
        end
        if not staff or not p.Parent then return end
        ST.found[p] = true
        if on("st_on") then notify(L["Staff in server: "] .. p.Name) end
        if on("st_leave") then lp:Kick("Staff joined: " .. p.Name) end
    end)
end
